const {GB,forecast,reclaimable,validate}=StorageEngine;
const $=id=>document.getElementById(id);
const demo=()=>({source:'Demonstration dataset',capacity:1000*GB,used:742*GB,files:[['research/raw-footage.mov',180,'Media',42],['research/raw-footage-copy.mov',180,'Media',42,true],['datasets/vision-v3.zip',95,'Archives',18],['backups/vision-v3-copy.zip',95,'Archives',18,true],['design/product-library.png',46,'Images',12],['design/site-renders.jpg',38,'Images',7],['submissions/project-reports.pdf',32,'Documents',60],['submissions/presentations.pptx',24,'Documents',10],['models/checkpoints.bin',22,'Other',6],['media/lab-demo.mp4',16,'Media',2],['notes/research.pdf',8,'Documents',3],['assets/icons.svg',6,'Images',4]].map(([name,size,category,ageDays,duplicate])=>({name,size:size*GB,category,ageDays,duplicate:!!duplicate}))});
let data=demo(),preview=false;
const colors=['#264d3d','#87a576','#c2cda0','#c6ad7d','#d9dfd0'];
function fmt(n){if(n>=GB)return (n/GB).toFixed(1)+' GB';if(n>=1e6)return(n/1e6).toFixed(1)+' MB';if(n>=1000)return(n/1000).toFixed(1)+' KB';return n+' B'}
function toast(s){$('toast').textContent=s;$('toast').hidden=false;setTimeout(()=>$('toast').hidden=true,4500)}
function render(){const growth=Number($('growth').value)*GB, reclaim=reclaimable(data.files),days=forecast(data.used,data.capacity,growth);$('source').textContent=data.source;$('sourceInfo').textContent=data.source==='Folder scan'?`· ${data.files.length} files · ${data.errors||0} unreadable entries · ${data.scannedAt||'scan time unavailable'}`:'· 12 representative files · simulated workload';$('used').textContent=fmt(data.used);$('usedSub').textContent=`of ${fmt(data.capacity)} volume capacity · ${(100*data.used/data.capacity).toFixed(1)}% used`;$('usageBar').style.width=Math.min(100,100*data.used/data.capacity)+'%';$('runway').textContent=days===null?'No growth':days+' days';$('risk').textContent=days!==null&&days<30?'Capacity attention needed':'Within 30-day capacity';$('reclaim').textContent=fmt(reclaim);$('growthValue').textContent=fmt(growth)+'/day';$('fileCount').textContent=data.files.length;$('scope').textContent=`${fmt(data.files.reduce((s,f)=>s+f.size,0))} in scanned inventory`;
const totals={};for(const f of data.files)totals[f.category||'Other']=(totals[f.category||'Other']||0)+f.size;const total=Object.values(totals).reduce((a,b)=>a+b,0);let offset=0;const stops=[];$('categories').replaceChildren();Object.entries(totals).sort((a,b)=>b[1]-a[1]).forEach(([name,size],i)=>{const color=colors[i%colors.length],start=offset;offset+=total?size/total*100:0;stops.push(`${color} ${start}% ${offset}%`);const row=document.createElement('div');row.className='cat';const dot=document.createElement('i');dot.style.background=color;const label=document.createTextNode(name);const value=document.createElement('span');value.textContent=fmt(size);row.append(dot,label,value);$('categories').append(row)});$('ring').style.background=total?`conic-gradient(${stops.join(',')})`:'#e0e6df';draw(growth,reclaim);renderFiles();if(preview)renderPlan();}
function draw(growth,reclaim){const max=Math.max(data.capacity*1.15,data.used+growth*30),x=d=>55+d/30*675,y=v=>205-v/max*175;let svg='';for(let i=0;i<4;i++){const v=max*i/3;svg+=`<line x1="55" y1="${y(v)}" x2="730" y2="${y(v)}" stroke="#e6eadd"/><text x="0" y="${y(v)+4}" fill="#8a9685" font-size="10">${(v/GB).toFixed(0)} GB</text>`}svg+=`<line x1="55" y1="${y(data.capacity)}" x2="730" y2="${y(data.capacity)}" stroke="#b29c6b" stroke-dasharray="5 5"/>`;const p=(used)=>Array.from({length:31},(_,d)=>`${x(d)},${y(used+growth*d)}`).join(' ');svg+=`<polygon points="55,205 ${p(data.used)} 730,205" fill="#e8eedf" opacity=".7"/><polyline points="${p(data.used)}" fill="none" stroke="#285d46" stroke-width="3"/><polyline points="${p(Math.max(0,data.used-reclaim))}" fill="none" stroke="#9eb980" stroke-width="2" stroke-dasharray="6 4"/>`;for(const d of [0,7,14,21,30])svg+=`<text x="${x(d)}" y="235" text-anchor="middle" fill="#8a9685" font-size="10">${d===0?'Today':'Day '+d}</text>`;$('chart').innerHTML=svg}
function renderFiles(){const q=$('search').value.toLowerCase();$('fileRows').replaceChildren();const files=data.files.filter(f=>f.name.toLowerCase().includes(q));for(const f of files){const tr=document.createElement('tr');for(const value of [f.name,f.category||'Other',fmt(f.size),`${f.ageDays??'—'} days`,f.duplicate?'Extra copy':'Retain']){const td=document.createElement('td');td.textContent=value;tr.append(td)}$('fileRows').append(tr)}if(!files.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=5;td.textContent='No matching files.';tr.append(td);$('fileRows').append(tr)}}
function renderPlan(){const bytes=reclaimable(data.files),growth=Number($('growth').value)*GB;const after=forecast(Math.max(0,data.used-bytes),data.capacity,growth);$('plan').hidden=false;$('plan').textContent=`Preview: ${data.files.filter(f=>f.duplicate).length} extra copies · ${fmt(bytes)} recoverable · projected usage after cleanup ${fmt(Math.max(0,data.used-bytes))} · ${after===null?'no projected growth':after+' days of runway'}. Review file ownership and backup requirements before taking any action outside this application. `;const b=document.createElement('button');b.className='textbutton';b.textContent='View matching files →';b.onclick=()=>switchView('files');$('plan').append(b);$('simulate').textContent='Cleanup preview active ✓'}
function switchView(view){document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!==view);document.querySelectorAll('nav button').forEach(el=>el.classList.toggle('active',el.dataset.view===view))}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>switchView(b.dataset.view));$('growth').oninput=render;$('search').oninput=renderFiles;$('simulate').onclick=()=>{preview=true;renderPlan()};$('review').onclick=()=>{preview=true;renderPlan();$('plan').scrollIntoView({behavior:'smooth',block:'center'})};$('reset').onclick=()=>{data=demo();preview=false;$('plan').hidden=true;$('simulate').textContent='Preview cleanup ↗';$('growth').value=6;render();toast('Demonstration dataset restored')};$('import').onclick=()=>$('upload').click();$('upload').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>20*1e6)throw Error('Please import a JSON file under 20 MB.');data=validate(JSON.parse(await f.text()));data.source='Folder scan';preview=false;$('plan').hidden=true;$('simulate').textContent='Preview cleanup ↗';render();toast('Folder inventory imported. Data stays in this browser tab.')}catch(err){toast(err.message)}e.target.value=''};render();
